create table if not exists public.routine_bundles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, bundle_key text not null, parent_title text not null, domain text not null, preferred_window text, default_importance smallint not null default 3 check (default_importance between 1 and 5), default_duration_minutes integer, schedule_template jsonb not null default '{}'::jsonb, active boolean not null default true, source text not null default 'me_plus', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,bundle_key), unique(id,user_id));
